export type Card = {
  monster: string;
  rank?: number;
};

export function scoreArmy(army: Card[]): number {
  if (!army.some((card) => card.monster === "sphinx")) return 0;
  const otherTypes = new Set(
    army.filter((card) => card.monster !== "sphinx").map((card) => card.monster),
  ).size;
  return 1 + (otherTypes > 3 ? 2 * (otherTypes - 3) : 1);
}

