export type Monster =
  | "sphinx"
  | "undead-warrior"
  | "zombie"
  | "hydra"
  | "cyclops"
  | "orthrus"
  | "chimera";

export type Card = {
  monster: Monster;
  rank?: number;
};

const SPHINX: Monster = "sphinx";

export function scoreArmy(army: Card[]): number {
  return army
    .filter((card) => card.monster === SPHINX)
    .map((sphinx) => scoreSphinx(sphinx, army))
    .reduce((total, points) => total + points, 0);
}

