function scoreSphinx(sphinx: Card, army: Card[]): number {
  const typesSeen = new Set(
    army.filter((card) => card !== sphinx).map((card) => card.monster),
  ).size;
  return 1 + (typesSeen > 3 ? 2 * (typesSeen - 3) : 1);
}

